const b=$input.first().json.body||{};
const p=b.parameters||b||{};
const email=((p.email||'')+'').trim();
const name=(p.name||p.full_name||'there');
const KEY='<JWT_REDACTED>';
if(!email){ return [{json:{to:'',subject:'',html:''}}]; }
try{ await this.helpers.httpRequest({method:'POST',url:'https://zkylrolpuwybsksspblj.supabase.co/rest/v1/casas_subscribers',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:{email:email,name:name,source:'registration'},json:true}); }catch(e){}
let tpl=''; try{ tpl=await this.helpers.httpRequest({method:'GET',url:'https://andreytry.github.io/hotel-concierge-demo/newsletter.html'}); }catch(e){ tpl=''; }
if(typeof tpl!=='string'){ tpl=String(tpl); }
function row(t,d,last){ const bd=last?'':'border-bottom:1px solid rgba(10,22,38,.12);'; return '<tr><td style="padding:14px 0;'+bd+'"><div style="font-family:Georgia,serif;font-size:19px;color:#0a1626;">'+t+'</div><div style="font-size:13.5px;color:#6f7789;margin-top:3px;">'+d+'</div></td></tr>'; }
const first=((name||'there')+'').split(' ')[0];
const welcomeRows=row('Your 10% direct rate is ready','Book any apartment direct with us and save — no platform fees, ever.',false)+row('Steps from Bayside and the bay','Downtown Miami, a three-minute walk to the marina.',false)+row('A concierge on hand','Ask us anything, any hour, in English or Spanish.',true);
const newsRows=row('World Cup quarter-final in Miami','Sat July 11 at Hard Rock Stadium — the city is buzzing.',false)+row('Third-place final, July 18','The last Miami match of the tournament, at Hard Rock Stadium.',false)+row('Free Fan Festival at Bayfront Park','Every match on big screens, a short walk from your door.',true);
const welcomeHtml=tpl.split('{{first_name}}').join(first).split('{{events_html}}').join(welcomeRows);
const newsHtml=tpl.split('{{first_name}}').join(first).split('{{events_html}}').join(newsRows);
return [
 {json:{to:email,subject:'Welcome to The Casas Collection — your direct rate inside',html:welcomeHtml}},
 {json:{to:email,subject:"What's on in Miami this week — The Casas Collection",html:newsHtml}}
];
